const resultados = [];
const eventos = $input.all();
const eventosProcesados = new Set(); 

let todosLosReclutadores = [];
try {
    todosLosReclutadores = $('CargarReclutadores').all().map(r => r.json);
} catch(e) {}

for (let i = 0; i < eventos.length; i++) {
    const evento = eventos[i].json;

    if (!evento.id || eventosProcesados.has(evento.id)) continue;
    eventosProcesados.add(evento.id);

    const descripcion = evento.description || '';

    // 🔎 BUSCAMOS EL TELÉFONO (Filtro de seguridad)
    const telMatch = descripcion.match(/Tel[:\s]*([0-9]{10,13})/i);
    const telefonoCandidato = telMatch ? telMatch[1] : null;

    // 🚫 SI NO HAY TELÉFONO, NO ES UNA CITA LISTA. LA IGNORAMOS.
    if (!telefonoCandidato) {
        continue; 
    }

    const nombreMatch = descripcion.match(/Nombre[:\s]*([^\n]+)/i);
    const nombreCandidato = nombreMatch ? nombreMatch[1].trim() : 'Nombre';

    let horaFormateada = 'hora por confirmar';
    try {
        const fechaISO = evento.start?.dateTime || evento.start?.date;
        const fecha = new Date(fechaISO);
        horaFormateada = fecha.toLocaleString('es-MX', {
            timeZone: 'America/Mexico_City',
            weekday: 'long',
            day: 'numeric',
            month: 'long',
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });
    } catch(e) {}

    let nombreReclutador = 'Tu equipo';
    let emojiReclutador = '📅';
    let telefonoReclutador = '5213323379399';
    let reclutadoresExtra = [];

    const recData = todosLosReclutadores.find(r => 
        evento.organizer?.email === r.calendar_id || 
        evento.creator?.email === r.calendar_id ||
        (evento.attendees && evento.attendees.some(a => a.email === r.calendar_id))
    );

    const reclutadorFinal = recData || (todosLosReclutadores.length > 0 ? todosLosReclutadores[0] : null);

    if (reclutadorFinal) {
        nombreReclutador = reclutadorFinal.nombre_reclutador || nombreReclutador;
        emojiReclutador = reclutadorFinal.emoji || emojiReclutador;
        telefonoReclutador = reclutadorFinal.telefono_reclutador || telefonoReclutador;
        reclutadoresExtra = reclutadorFinal.reclutadores_extra || [];
    }

    const mensajeReclutador = `⏰ *¡RECORDATORIO DE ENTREVISTA MAÑANA!* ${emojiReclutador}\n\nHola ${nombreReclutador}, tienes una cita programada:\n\n👤 *Candidato:* ${nombreCandidato}\n📱 *Tel:* wa.me/${telefonoCandidato}\n🕒 *Cuando:* ${horaFormateada}\n\n📝 _Evento: ${evento.summary || 'Entrevista'}_`;

    const mensajeCandidato = `Hola ${nombreCandidato}, te recordamos que mañana tienes tu entrevista:\n\n🕒 ${horaFormateada}\n\nTe esperamos. Cualquier duda, escríbenos. ✨`;

    resultados.push({
        json: {
            mensaje_reclutador: mensajeReclutador,
            telefono_reclutador: telefonoReclutador,
            mensaje_candidato: mensajeCandidato,
            telefono_candidato: telefonoCandidato,
            evento_valido: true,
            reclutadores_extra: reclutadoresExtra
        }
    });
}

return resultados;

const fs = require('fs');

// 1. Leer el equipo desde el JSON externo
const rutaArchivo = '/home/node/virgo_files/functions/config_reclutadores.json';
let equipo = [];

try {
    const rawData = fs.readFileSync(rutaArchivo, 'utf8');
    equipo = JSON.parse(rawData);
} catch (error) {
    console.log('Error leyendo config_reclutadores.json: ' + error.message);
    equipo = [{
        nombre: 'Admin',
        emoji: '🛡️',
        telefono: '5213323379399',
        calendar_id: 'sistemasdulvirgo@gmail.com'
    }];
}

// 2. Limpiar espacios y filtrar solo los que tienen calendar_id válido
equipo = equipo
    .map(r => ({
        ...r,
        telefono: (r.telefono || '').trim(),       // FIX 1: quitar espacios
        calendar_id: (r.calendar_id || '').trim()  // FIX 1: quitar espacios
    }))
    .filter(r => r.calendar_id.includes('@'));

// 3. FIX 2: Eliminar calendar_ids duplicados
//    Si dos reclutadores comparten calendario, solo se consulta una vez
//    pero se notifica a ambos reclutadores
const calendariosVistos = {};
const equipoSinDuplicados = [];

for (const reclutador of equipo) {
    if (!calendariosVistos[reclutador.calendar_id]) {
        // Primer reclutador con este calendario
        calendariosVistos[reclutador.calendar_id] = [reclutador];
        equipoSinDuplicados.push(reclutador);
    } else {
        // Calendario ya existe: agregar este reclutador como "extra"
        // para que también reciba notificación
        calendariosVistos[reclutador.calendar_id].push(reclutador);
    }
}

// 4. Calcular rango de mañana
const manana = new Date();
manana.setDate(manana.getDate() + 1);

const inicioManana = new Date(manana);
inicioManana.setHours(0, 0, 0, 0);

const finManana = new Date(manana);
finManana.setHours(23, 59, 59, 999);

// 5. FIX 3: Pasar datos del reclutador explícitamente en cada item
//    incluyendo reclutadores extra que comparten el mismo calendario
return equipoSinDuplicados.map(reclutador => ({
    json: {
        nombre_reclutador: reclutador.nombre,
        emoji: reclutador.emoji || '📅',
        telefono_reclutador: reclutador.telefono,
        calendar_id: reclutador.calendar_id,
        time_min: inicioManana.toISOString(),
        time_max: finManana.toISOString(),
        // Lista de todos los reclutadores que comparten este calendario
        // (para notificar a cada uno)
        reclutadores_extra: calendariosVistos[reclutador.calendar_id]
            .slice(1) // el primero ya es el principal
            .map(r => ({
                nombre: r.nombre,
                emoji: r.emoji || '📅',
                telefono: r.telefono
            }))
    }
}));

